"""Versioned beginner curriculum. Learner code is never executed by Django."""

def case(inputs, expected):
    return {'inputs': inputs, 'expected': expected}


def mission(slug, title, subtitle, minutes, concepts, sections, example, trace, challenge,
            starter, cases, question, options, answer, explanation, hints, solution):
    return dict(slug=slug, title=title, subtitle=subtitle, minutes=minutes, concepts=concepts,
                sections=sections, example=example, trace=trace, challenge=challenge,
                starter=starter, cases=cases, question=question, options=options, answer=answer,
                quiz_explanation=explanation, hints=hints, solution=solution, version=1)


